bool loadFontFile(const std::wstring& path,bool select){PrivateFontCollection selectedFont;if(selectedFont.AddFontFile(path.c_str())!=Ok||privateFonts->AddFontFile(path.c_str())!=Ok)return false;AddFontResourceExW(path.c_str(),FR_PRIVATE,0);int n=selectedFont.GetFamilyCount(),found=0;if(n<1)return false;auto families=std::make_unique<FontFamily[]>(n);selectedFont.GetFamilies(n,families.get(),&found);wchar_t name[LF_FACESIZE]={};if(!found)return false;families[found-1].GetFamilyName(name);customFontFamily=name;privateFontNames.insert(customFontFamily);for(auto& d:localDefs["ClickGUI"])if(d[0]=="Font"){if(std::find(d[3].begin(),d[3].end(),utf(customFontFamily))==d[3].end())d[3].push_back(utf(customFontFamily));}if(select)values["ClickGUI"]["Font"]=utf(customFontFamily);prefs["fontFile"]=utf(path);fontCache.clear();return true;}
void txt(Graphics&g,std::string text,float x,float y,float w,float h,Color c,float size=12){if(w<=0||h<=0||y+h<clipTop||y>clipBottom)return;float fontScale=(float)std::clamp(nv("ClickGUI","Font Size",12)/12,.75,1.5);size*=fontScale;if(drawOpacity<1)c=Color((BYTE)(c.GetAlpha()*drawOpacity),c.GetRed(),c.GetGreen(),c.GetBlue());auto renderFont=fontName;auto unicode=wide(text);if(fontName==L"Mojangles"&&std::any_of(unicode.begin(),unicode.end(),[](wchar_t c){return c>=0x2e80;}))renderFont=L"Segoe UI";auto key=std::make_pair(renderFont,(int)std::round(size*10));if(fontCache.size()>128)fontCache.clear();auto&f=fontCache[key];if(!f){f=std::make_unique<Font>(renderFont.c_str(),size,FontStyleRegular,UnitPixel,privateFontNames.count(renderFont)?privateFonts.get():nullptr);if(f->GetLastStatus()!=Ok)f=std::make_unique<Font>(L"Segoe UI",size,FontStyleRegular,UnitPixel);}SolidBrush b(c);StringFormat fmt;if(h<=26)fmt.SetFormatFlags(StringFormatFlagsNoWrap);fmt.SetTrimming(StringTrimmingEllipsisCharacter);g.DrawString(unicode.c_str(),(INT)unicode.size(),f.get(),RectF(x,y,w,h),&fmt,&b);}
void txtRight(Graphics&g,const std::string&text,float x,float y,float w,float h,Color c,float size){auto saved=g.Save();auto ws=wide(text);float fs=std::clamp(nv("ClickGUI","Font Size",12)/12,.75,1.5);Font f(fontName.c_str(),size*fs,FontStyleRegular,UnitPixel,privateFontNames.count(fontName)?privateFonts.get():nullptr);StringFormat fmt;fmt.SetFormatFlags(StringFormatFlagsNoWrap);fmt.SetAlignment(StringAlignmentFar);SolidBrush b(c);g.DrawString(ws.c_str(),(INT)ws.size(),&f,RectF(x,y,w,h),&fmt,&b);g.Restore(saved);}

