std::string description(std::string m,std::string k=""){static const std::map<std::string,std::string>mods={{"Circle","Arrange bots evenly in a stationary circle around the player."},{"Orbit","Circle the player while maintaining an evenly spaced ring."},{"ClickGUI","Customize GUI colors, fonts, separators, animations and shaders."},{"Weather","Show Snow, Rain, Lava or Crystal background particles."},{"Notification","Show operation results and remaining time."},{"KillAura","Attack selected targets with a sword. Respects target and range settings."},{"CrystalAura","Place and break crystals around targets."},{"PistonCrystal","Push and detonate crystals with pistons."},{"Offhand","Refill the offhand with totems. Packet prioritizes refill; Spam repeats confirmed swaps."},{"Jetpack","Use crystal explosions to approach. Requires a totem and minimum health."},{"AutoBack","Automatically send /back after respawning."},{"HUDIGNGPT","Ask about selected bots and change GUI settings."},{"Gemini","Configure the in-game IGNGPT model and allowed players."},{"Spam","Send configured public chat messages in sequence."},{"TellSpam","Send messages to the configured MCID using /tell."},{"ChatQueue","Configure chat intervals and queue limits, or clear the queue."},{"AutoTPA","Send TPA requests from each selected online bot."},{"Friendlist","Friends are excluded from attacks."},{"EnemyList","Enemy targets used by the Enemies target mode."},{"MicrosoftLogin","Start Microsoft authentication for one selected bot and display its code."},{"KitNow","Left-click to request the configured kit."},{"WorldNow","Left-click to join the configured world."},{"CustomCommand","Left-click to send the configured command."},{"Scaffold","Toggle automatic block placement."}};static const std::map<std::string,std::string>fields={{"Description","Show descriptions when hovering over modules and settings."},{"Shader Outline","Draw an outline around GUI panels and HUDs."},{"Rotation Delay","Wait after rotating before the next attack or placement, in milliseconds."},{"Packet","Prioritize totem refill over normal equipment actions."},{"Spam","Repeat spare totem swaps after server confirmation."},{"Interval","Repeat interval: milliseconds for Offhand, seconds for chat."},{"Targets","Enemies targets registered enemies. All Players excludes friends and bots."},{"Direction","Choose the movement direction."},{"Shader Direction","Angle of shader movement."},{"Expand Duration","Settings opening and closing duration in milliseconds."},{"Animation","Fade changes opacity; Slide expands height; None opens instantly."},{"Separators","Draw a thin separator between modules."},{"Glow","Add a soft glow around the outline."},{"Duration","Notification lifetime in seconds. The bar shows remaining time."},{"Font","Display font. Mojangles is bundled with the app."}};if(!k.empty()){auto it=fields.find(k);if(it!=fields.end())return it->second;return label(m)+" / "+k+" setting.";}auto it=mods.find(m);if(it!=mods.end())return it->second;return label(m)+" : left-click to operate; right-click to open available settings.";}
